<?php
require_once __DIR__ . '/helpers.php';
require_once __DIR__ . '/erp_migrations.php';
require_once __DIR__ . '/app/Services/MachineAttachment.php';
require_once __DIR__ . '/app/Services/InventoryService.php';
$requestedPage = (string) ($_GET['page'] ?? 'overview');
// The machines area does not use the spreadsheet/routing services. Loading
// those unrelated files here made machine documents fail on older production
// PHP runtimes before the attachment route could send the PDF.
if ($requestedPage !== 'machines' && $requestedPage !== 'machine_attachment') {
    require_once __DIR__ . '/app/Services/ArticleSpreadsheet.php';
    require_once __DIR__ . '/app/Services/RawMaterialSpreadsheet.php';
    require_once __DIR__ . '/app/Services/RawMaterialImportReferenceResolver.php';
    require_once __DIR__ . '/app/Services/CustomerSpreadsheet.php';
    require_once __DIR__ . '/app/Services/SupplierSpreadsheet.php';
    require_once __DIR__ . '/app/Services/RoutingService.php';
}
require_login();
erp_run_phase1_migrations($pdo);
$userId = (int) $_SESSION['user_id'];
$user = current_user($pdo) ?: [];
$isAdmin = is_admin($pdo, $userId);
$profile = (string) ($user['access_profile'] ?? 'Utilizador');
if (!erp_user_can($pdo, $user, 'erp.view')) { http_response_code(403); exit('Acesso reservado ao ERP.'); }

if ($requestedPage === 'machine_attachment') {
    $attachmentId = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT);
    if (!$attachmentId || $attachmentId < 1) {
        http_response_code(404);
        exit('Documento não encontrado.');
    }

    $stmt = $pdo->prepare(
        'SELECT a.* FROM erp_machine_attachments a '
        . 'INNER JOIN erp_machines m ON m.id = a.machine_id '
        . 'WHERE a.id = ? AND a.deleted_at IS NULL AND m.deleted_at IS NULL LIMIT 1'
    );
    $stmt->execute([$attachmentId]);
    $attachment = $stmt->fetch(PDO::FETCH_ASSOC);
    $absolutePath = $attachment
        ? gt_machine_attachment_path(__DIR__, (string) ($attachment['file_path'] ?? ''))
        : '';
    if (!$attachment || $absolutePath === '') {
        http_response_code(404);
        exit('Documento não encontrado.');
    }

    $mime = gt_machine_attachment_mime($absolutePath, (string) ($attachment['original_name'] ?? ''));
    if ($mime === '') {
        $mime = 'application/octet-stream';
    }
    $fileName = trim((string) ($attachment['original_name'] ?? 'documento')) ?: 'documento';
    $asciiName = preg_replace('/[^A-Za-z0-9._-]/', '_', $fileName) ?: 'documento';
    header('Content-Type: ' . $mime);
    header('Content-Length: ' . (string) filesize($absolutePath));
    header('Content-Disposition: inline; filename="' . $asciiName . '"; filename*=UTF-8\'\'' . rawurlencode($fileName));
    header('X-Content-Type-Options: nosniff');
    header('Cache-Control: private, no-store, max-age=0');
    readfile($absolutePath);
    exit;
}

function erp_count(PDO $pdo, string $sql): int { return (int) $pdo->query($sql)->fetchColumn(); }
function erp_money(float $value): string { return number_format($value, 2, ',', '.') . ' €'; }
function erp_page_url(string $page): string { return 'erp.php?page=' . urlencode($page); }
function erp_raw_material_spreadsheet_columns(): array { return RawMaterialSpreadsheet::columns(); }
function erp_read_raw_material_spreadsheet(string $path,string $extension): array { return RawMaterialSpreadsheet::read($path,$extension); }
function erp_article_fields(): array { return ['material','bag_color','width_tolerance','length_tolerance','front_colors','back_colors','pallet_dimensions','pallet_lid','pallet_straps','pallet_film','microperforation','has_handle','has_holes','has_gusset','centered_gusset','gusset_length','composition','theoretical_weight','thread_color','perforation_type','seam_type','lot_identification_rule','analysis_grammage','analysis_total_weight','analysis_apparent_width','analysis_gusset_width','analysis_bag_height','analysis_break_height','analysis_break_length','analysis_seam_strength','analysis_static_friction','analysis_dynamic_friction','analysis_air_permeability']; }
