<script>
(function () {
  var addAddress = document.querySelector('[data-add-delivery-address]');
  if (addAddress) {
    var addressList = document.querySelector('[data-delivery-addresses]');
    var addressTemplate = document.querySelector('[data-delivery-address-template]');
    addAddress.addEventListener('click', function () { addressList.appendChild(addressTemplate.content.cloneNode(true)); });
    document.addEventListener('click', function (event) { var button=event.target.closest('[data-remove-delivery-address]'); if(button) button.closest('[data-delivery-row]').remove(); });
  }

  var articleSelect=document.querySelector('[data-of-article]');
  var addressSelect=document.querySelector('[data-of-delivery-address]');
  var transporter=document.querySelector('[data-of-transporter]');
  var addressesByCustomer=<?=json_encode($deliveryAddressesByCustomer, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
  function refreshTransporter(){var option=addressSelect&&addressSelect.options[addressSelect.selectedIndex];if(transporter)transporter.value=option&&option.dataset.transporter||'';}
  function refreshAddresses(){if(!articleSelect||!addressSelect)return;var article=articleSelect.options[articleSelect.selectedIndex];var addresses=addressesByCustomer[article&&article.dataset.customerId]||[];addressSelect.innerHTML='';if(!addresses.length){var empty=document.createElement('option');empty.value='';empty.textContent='Este cliente não tem moradas de entrega configuradas';addressSelect.appendChild(empty);addressSelect.disabled=true;}else{addressSelect.disabled=false;addresses.forEach(function(address){var option=document.createElement('option');option.value=address.id;option.dataset.transporter=address.transporter;option.textContent=address.label+' — '+address.address+', '+(address.postal_code||'')+' '+(address.city||'');addressSelect.appendChild(option);});}refreshTransporter();}
  if(articleSelect){articleSelect.addEventListener('change',refreshAddresses);addressSelect.addEventListener('change',refreshTransporter);refreshAddresses();}
})();
</script>
